  FT["PH-H8323"] = {"id":"PH-H8323","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9865_2009.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将碧瑶市 New Lucban 描笼涯的 Pines City 国立中学－Magsaysay 附属校从该校分离，改设为名为 Magsaysay 国立中学的独立国立中学并拨款","en":"An Act Separating the Pines City National High School - Magsaysay Annex in Barangay New Lucban, City of Baguio from the Pines City National High School, Converting it into an Independent National High School to Be Known as Magsaysay National High School and Appropriating Funds Therefor","orig":"An Act Separating the Pines City National High School - Magsaysay Annex in Barangay New Lucban, City of Baguio from the Pines City National High School, Converting it into an Independent National High School to Be Known as Magsaysay National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 9865","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-12-20","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9865_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8323-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into a National High School. - The Pines City National High School - Magsaysay Annex in Barangay New Lucban, City of Baguio is hereby separated from the Pines City National High School and converted into an independent national high school to be known as Magsaysay National High School."}},{"id":"PH-H8323-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. - All personnel, assets, liabilities and records of the Pines City National High School - Magsaysay Annex are hereby transferred to and absorbed by the Magsaysay National High School."}},{"id":"PH-H8323-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department’s program the operationalization of the Magsaysay National High School, the initial funding of which shall be charged against the current year's appropriations of the Pines City National High School - Magsaysay Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8323-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. - The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8323-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p118","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Pines City National High School - Magsaysay Annex in Barangay New Lucban, City of Baguio from the Pines City National High School, Converting it into an Independent National High School to Be Known as Magsaysay National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8324"] = {"id":"PH-H8324","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9866_2009.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Lagawe市","en":"An Act Converting the Ayangan National High School in Barangay Ponghal, Municipality of Lagawe, Province of Ifugao into a National Agricultural and Vocational High School to Be Known as Ayangan National Agricultural and Vocational High School and Appropriating Funds Therefor","orig":"An Act Converting the Ayangan National High School in Barangay Ponghal, Municipality of Lagawe, Province of Ifugao into a National Agricultural and Vocational High School to Be Known as Ayangan National Agricultural and Vocational High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education","environment"],"docNumber":"Republic Act No. 9866","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-12-20","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9866_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8324-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Conversion into a National Agricultural and Vocational High School. - The Ayangan National High School in Barangay Ponghal, Municipality of Lagawe, Province of Ifugao is hereby converted into a national agricultural and vocational high school to be known as Ayangan National Agricultural and Vocational High School."}},{"id":"PH-H8324-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. - All personnel, assets, liabilities and records of the Ayangan National High School are hereby transferred to and absorbed by the Ayangan National Agricultural and Vocational High School."}},{"id":"PH-H8324-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department’s program the operationalization of the Ayangan National Agricultural and Vocational High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8324-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. - The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8324-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p118"};
  FT["PH-H8325"] = {"id":"PH-H8325","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9867_2009.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将伊富高省 Hingyon 市镇 Bitu 描笼涯的 Hingyon 国立中学附属校分离，改设为独立的 Southern Hingyon 国立中学，并为此拨款","en":"An Act Separating the Hingyon National High School Annex in Barangay Bitu, Municipality of Hingyon, Province of Ifugao from the Hingyon National High School, Converting it into a Separate and Independent National High School to Be Known as Southern Hingyon National High School and Appropriating Funds Therefor","orig":"An Act Separating the Hingyon National High School Annex in Barangay Bitu, Municipality of Hingyon, Province of Ifugao from the Hingyon National High School, Converting it into a Separate and Independent National High School to Be Known as Southern Hingyon National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 9867","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-12-20","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9867_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8325-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into a National High School. – The Hingyon National High School Annex in Barangay Bitu, Municipality of Hingyon, Province of Ifugao is hereby separated from the Hingyon National High School and converted into an independent national high school to be known as Southern Hingyon National High School."}},{"id":"PH-H8325-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. - All personnel, assets, liabilities and records of the Hingyon National High School Annex are hereby transferred to and absorbed by the Southern Hingyon National High School."}},{"id":"PH-H8325-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department’s program the operationalization of the Southern Hingyon National High School, the initial funding of which shall be charged against the current year's appropriations of the Hingyon National High School Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8325-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. - The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8325-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p118","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Hingyon National High School Annex in Barangay Bitu, Municipality of Hingyon, Province of Ifugao from the Hingyon National High School, Converting it into a Separate and Independent National High School to Be Known as Southern Hingyon National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
